QGraphicsItem *optionItem(DrawingSheetEditor &e,const QUuid &id,const QString &kind){for(auto *i:e.canvas()->scene()->items())if(i->data(1).toUuid()==id&&i->data(0).toString()==kind)return i;throw std::runtime_error("oggetto opzioni assente");}
void optionMouse(DrawingSheetEditor &e,QPointF point,QEvent::Type type,Qt::KeyboardModifiers modifiers=Qt::NoModifier){auto *v=e.canvas();const QPointF local=v->mapFromScene(point),global=v->viewport()->mapToGlobal(local.toPoint());QMouseEvent event(type,local,global,type==QEvent::MouseMove?Qt::NoButton:Qt::LeftButton,type==QEvent::MouseButtonRelease?Qt::NoButton:Qt::LeftButton,modifiers);QApplication::sendEvent(v->viewport(),&event);}
void typeNumeric(QDoubleSpinBox *spin,const QString &text){spin->setValue(0);auto *line=spin->findChild<QLineEdit *>();line->selectAll();for(auto c:text){QKeyEvent event(QEvent::KeyPress,0,Qt::NoModifier,QString(c));QApplication::sendEvent(line,&event);}spin->interpretText();}
